/* Generated by content/cna/build_cna.py from content/cna/cna_src.py. Edit the source, then re-run the build. */
/* CNA guide chapters 2-7. Same format as the HHA data files (see data/hha-a.js). Sources: content/SOURCES.md */
(window.CNA = window.CNA || []).push(
{"ch": 2, "bp": ["Egzamen ekri MA: Wòl ak responsablite (9 kesyon sou 60) ak Kominikasyon (5).", "MA written exam: Role and Responsibility (9 of 60 questions) and Communication (5)."], "title": ["Wòl ou nan yon mezon retrèt", "Your role in a nursing home"], "src": ["S1", "S21", "S22", "S28", "S29", "S25", "S26", "S27", "S24"], "sections": [{"h": ["Lè w aksepte yon travay", "Taking on a task"], "src": ["S1", "S28", "S29"], "b": [["p", "Yon enfimyè (RN) ka ba w anpil travay pou w fè. Chak travay dwe klè, epi yon moun dwe sipèvize l.", "A registered nurse (RN) can assign or delegate many tasks to you. Each task must be clear and supervised."], ["li", "Anvan w aksepte yon travay, tcheke 4 «S» yo: Scope (limit travay ou), Supervision (siveyans), Safety (sekirite) ak Supplies (materyèl).", "Before you accept a task, check the 4 S's: Scope, Supervision, Safety and Supplies."], ["li", "Pa fè yon konpetans ou pa t aprann. Menm yon konpetans ou te konn fè ka bezwen fòmasyon ankò, tankou yon leve mekanik.", "Do not do a skill you were not trained for. Even a skill you learned before may need retraining, for example a mechanical lift."], ["li", "Si w pa gen bon materyèl la, travay la pa an sekirite. Si w pa sèten, mande enfimyè a.", "If you do not have the right equipment, the task is not safe. If you are unsure, ask the nurse."], ["li", "Travay prensipal ou se ede rezidan yo ak aktivite lavi chak jou (ADL) epi rapòte bay enfimyè a nenpòt chanjman nan eta yon rezidan.", "Your main job is to help residents with activities of daily living (ADLs) and to report any change in a resident's condition to the nurse."], ["li", "Swiv plan swen an. Si w panse yon bagay ladan l ta dwe chanje, di enfimyè a. Pa chanje l poukont ou.", "Follow the care plan. If you think something in it should change, tell the nurse. Do not change it yourself."], ["li", "Règ fòmasyon federal yo bay lis konpetans swen pèsonèl yon asistan enfimyè: benyen, swen kò (tankou swen bouch), abiye, twalèt, ak ede moun nan manje ak bwè.", "Federal training rules list the personal care skills of a nurse aide: bathing, grooming (including mouth care), dressing, toileting, and help with eating and drinking."], ["li", "Medikaman: nan Massachusetts, se sèlman yon CNA ki gen sètifika Asistan Medikaman (Certified Medication Aide) ki ka bay medikaman, sèlman kèk kalite, epi sèlman anba siveyans. Si w pa gen sètifika sa a, pa bay okenn medikaman.", "Medications: in Massachusetts, only a CNA who has also earned Certified Medication Aide certification may give medications, only certain kinds, and only under supervision. Without that certification, do not give any medication."], ["li", "Rapòte chanjman bay enfimyè a san reta. Rapò fèt nan kòmansman ak nan fen chak ekip, epi chak fwa gen yon chanjman enpòtan.", "Report changes to the nurse in a timely way. Reports happen at the start and end of every shift, and any time there is an important change."]]}, {"h": ["Devwa legal ak etik", "Legal and ethical duties"], "src": ["S1", "S25", "S26", "S27"], "b": [["li", "Kenbe tout enfòmasyon rezidan yo konfidansyèl (HIPAA), ansanm ak plan swen, dosye ak rapò chanjman ekip.", "Keep all resident information confidential (HIPAA), including care plans, records and shift reports."], ["li", "Pa aksepte kado ni pouboire nan men rezidan yo oswa fanmi yo.", "Do not accept gifts or tips from residents or their families."], ["li", "Lalwa oblije w rapòte: rapòte nenpòt siy abi oswa neglijans bay enfimyè a, epi rete ak rezidan an jiskaske pa gen lòt danje.", "You are a mandated reporter: report any sign of abuse or neglect to the nurse, and stay with the resident until no further harm can happen."], ["li", "Si yon rezidan di w li sibi abi, rapòte l menm si rezidan an konfonn.", "If a resident tells you about abuse, report it even if the resident is confused."], ["li", "Dosye a konfidansyèl: se sèlman moun ki dirèkteman nan swen rezidan an ki ka wè l. Si yon manm fanmi mande wè l, voye demann lan bay enfimyè a. Rezidan an gen dwa wè pwòp dosye pa l.", "The chart is confidential: only people directly involved in the resident's care may see it. If a family member asks to see it, refer the request to the nurse. The resident has the right to see their own records."], ["li", "Pa poste anyen sou rezidan yo ni pataje foto yo sou rezo sosyal. Règ federal yo konte foto oswa anrejistreman ki imilye oswa ki rabese yon rezidan kòm abi mantal.", "Do not post about residents or share their photos on social media. Federal rules count photos or recordings that demean or humiliate a resident as mental abuse."]]}, {"h": ["Kenbe sètifika w", "Staying certified"], "src": ["S21", "S22"], "b": [["li", "Yon etablisman pa ka fè w travay kòm asistan enfimyè plis pase 4 mwa si w poko fini yon pwogram fòmasyon ak evalyasyon ki apwouve.", "A facility may not use you as a nurse aide for more than 4 months unless you completed an approved training and competency program."], ["li", "Ou bezwen omwen 12 èdtan fòmasyon kontinyèl chak ane, ansanm ak swen moun ki gen demans ak prevansyon abi.", "You need at least 12 hours of in-service training every year, including dementia care and abuse prevention."], ["li", "Si w pase 24 mwa youn dèyè lòt san travay peye nan swen, ou dwe fè yon nouvo pwogram fòmasyon ak evalyasyon.", "If you go 24 months in a row without paid nursing work, you must complete a new training and competency program."]]}, {"h": ["Pale ak rezidan yo", "Talking with residents"], "src": ["S1", "S24", "S25"], "b": [["li", "Jès kò ak ton vwa w ka di plis pase pawòl ou.", "Body language and tone of voice can say more than your words."], ["li", "Sèvi ak mo senp. Evite mo medikal rezidan an ka pa konnen.", "Use plain words. Avoid medical terms the resident may not know."], ["li", "Bay rezidan an tout atansyon w. Diminye bri: fèmen pòt la oswa bese televizyon an, si l dakò.", "Give the resident your full attention. Reduce noise: close the door or turn down the TV, with their permission."], ["li", "Pou yon moun ki konfonn, ba l yon chwa senp: «Soup oswa sandwich?» olye «Kisa w vle pou manje midi?»", "For a person who is confused, offer a simple choice: \"Soup or a sandwich?\" instead of \"What do you want for lunch?\""], ["li", "Anvan nenpòt swen, eksplike sa w pral fè, pou rezidan an ka poze kesyon oswa di non. Rezidan yo gen dwa refize swen.", "Before any care, explain what you will do, so the resident can ask questions or say no. Residents have the right to refuse care."], ["li", "Si yon rezidan fache, koute l san kritike, pa defann tèt ou, epi kenbe chanm nan kalm e trankil.", "If a resident is angry, listen without criticizing, do not get defensive, and keep the room calm and quiet."], ["li", "Si yon rezidan mande w yon bagay ou pa ka reponn, tankou kesyon sou dyagnostik li, di enfimyè a pou yon moun ka swiv sa.", "If a resident asks something you cannot answer, such as questions about their diagnosis, tell the nurse so someone can follow up."], ["li", "Afazi fè l difisil pou moun nan pale oswa konprann mo. Sèvi ak fraz kout e senp, bay anpil tan, kite moun nan lonje dwèt oswa fè jès, epi pa korije jan l pale.", "Aphasia makes it hard to speak or understand words. Use short, simple sentences, give plenty of time, let the person point or gesture, and do not correct their speech."], ["li", "Aparèy pou tande: ede rezidan an mete yo anvan w pale, epi gade l an fas. Moun ki pa wè byen: di kiyès ou ye lè w ap antre nan chanm nan.", "Hearing aids: help the resident put them in before you talk, then face them. Low vision: say who you are as you enter the room."]]}], "terms": [["scope of practice", "limit travay ou"], ["delegation", "delegasyon"], ["mandated reporter", "moun lalwa oblije rapòte"], ["in-service training", "fòmasyon kontinyèl"], ["nonverbal communication", "kominikasyon san pawòl"]], "qs": [["n201", 2, ["delegation", "delegasyon"], ["Anvan w aksepte yon nouvo travay nan men enfimyè a, kisa pou w tcheke?", "Sèlman si w gen tan", "Si yon lòt asistan vle fè l", "Limit travay ou, siveyans, sekirite ak materyèl", "Si fanmi rezidan an dakò", "Tcheke 4 «S» yo: limit travay ou, siveyans, sekirite ak materyèl. Si youn ladan yo manke, pale ak enfimyè a anvan."], ["Before you accept a new task from the nurse, what should you check?", "Only whether you have time", "Whether another aide wants to do it", "Scope, supervision, safety and supplies", "Whether the resident's family agrees", "Check the 4 S's: Scope, Supervision, Safety and Supplies. If any of them is missing, talk to the nurse first."]], ["n202", 0, ["mechanical lift", "leve mekanik"], ["Enfimyè a mande w sèvi ak yon leve mekanik, men ou pa t janm aprann. Kisa ou fè?", "Di enfimyè a ou bezwen fòmasyon anvan w sèvi avè l", "Eseye l avèk prekosyon ak rezidan an", "Gade yon videyo sou telefòn ou epi sèvi avè l", "Leve rezidan an ak men w pito", "Pa fè yon konpetans ou pa t aprann. Yon leve ki mal itilize ka blese rezidan an ak ou menm. Mande fòmasyon anvan."], ["The nurse asks you to use a mechanical lift, but you were never trained on it. What do you do?", "Tell the nurse you need training before you use it", "Try it carefully with the resident", "Watch a video on your phone and then use it", "Lift the resident by hand instead", "Do not do a skill you were not trained for. A lift used wrong can injure the resident and you. Ask for training first."]], ["n203", 3, ["gratuity", "pouboire"], ["Pitit fi yon rezidan ofri w $20 pou di w mèsi pou bon swen an. Kisa ou fè?", "Aksepte l si pesonn pa wè", "Aksepte l epi pataje l ak ekip la", "Mande l yon kat kado pito", "Di l mèsi epi refize avèk politès", "Aksepte kado oswa pouboire nan men rezidan oswa fanmi pa etik. Di yo mèsi avèk jantiyès epi refize."], ["A resident's daughter offers you $20 to thank you for good care. What do you do?", "Accept it if no one sees", "Accept it and share it with the team", "Ask her for a gift card instead", "Thank her and politely refuse", "Accepting gifts or tips from residents or families is unethical. Thank them kindly and refuse."]], ["n204", 1, ["mandated reporter", "moun lalwa oblije rapòte"], ["Yon rezidan ki gen demans di w yon lòt asistan te souflete l yè swa. Kisa ou fè?", "Pa okipe l, paske li konfonn", "Rapòte l bay enfimyè a touswit", "Mande lòt asistan an si se vre", "Tann pou w wè si l ap di l ankò", "Lalwa oblije w rapòte. Rapòte sa yon rezidan di w sou abi, menm si l konfonn. Se pa ou ki mennen ankèt."], ["A resident with dementia tells you that another aide slapped her last night. What do you do?", "Ignore it, since she is confused", "Report it to the nurse right away", "Ask the other aide if it is true", "Wait to see if she says it again", "You are a mandated reporter. Report what a resident tells you about abuse, even if the resident is confused. You do not investigate."]], ["n205", 2, ["neglect", "neglijans"], ["Ou jwenn yon rezidan ki kouche nan yon kabann tranpe, poukont li, ap kriye, apre plizyè èdtan pesonn pa t reponn bouton apèl li. Pandan w ap tann enfimyè a, kisa ou fè?", "Ale fini ak lòt rezidan ou yo anvan", "Pran yon foto pou pwouve l", "Rete avè l epi asire w li an sekirite epi l jwenn swen", "Di fanmi l pou yo pote plent", "Rapòte neglijans posib la bay enfimyè a, epi rete ak rezidan an jiskaske w sèten pa gen lòt danje."], ["You find a resident lying in a soaked bed, alone and crying, after her call light went unanswered for hours. While you wait for the nurse, what do you do?", "Leave to finish your other residents first", "Take a photo to prove it", "Stay with her and make sure she is safe and cared for", "Tell her family to complain", "Report possible neglect to the nurse, and stay with the resident until you are sure no further harm can happen."]], ["n206", 1, ["in-service training", "fòmasyon kontinyèl"], ["Konbyen èdtan fòmasyon kontinyèl yon asistan enfimyè dwe fè chak ane?", "Omwen 6 èdtan", "Omwen 12 èdtan", "Omwen 40 èdtan", "Okenn apre w fin sètifye", "Règ federal yo mande omwen 12 èdtan pa ane, ansanm ak swen demans ak prevansyon abi."], ["How many hours of in-service training must a nurse aide complete each year?", "At least 6 hours", "At least 12 hours", "At least 40 hours", "None after you are certified", "Federal rules require at least 12 hours a year, including dementia care and abuse prevention."]], ["n207", 3, ["nurse aide registry", "rejis asistan enfimyè"], ["Ou te sispann travay kòm asistan enfimyè sa gen 2 zan (24 mwa youn dèyè lòt san travay peye nan swen). Kisa pou w fè anvan w travay ankò?", "Anyen; sètifika a pa janm ekspire", "Sèlman mete adrès ou ajou", "Travay 4 mwa, apre sa pase egzamen an", "Fè yon nouvo pwogram fòmasyon ak evalyasyon", "Apre 24 mwa youn dèyè lòt san travay peye nan swen, règ federal yo mande yon nouvo pwogram fòmasyon ak evalyasyon."], ["You stopped working as a nurse aide 2 years ago (24 months in a row with no paid nursing work). What must you do before working again?", "Nothing; certification never expires", "Only update your address", "Work 4 months, then take the test", "Complete a new training and competency program", "After 24 months in a row without paid nursing work, federal rules require a new training and competency evaluation program."]], ["n208", 0, ["competency evaluation", "evalyasyon konpetans"], ["Yon mezon retrèt anboche w anvan w fini pwogram fòmasyon ou. Pandan konbyen tan li ka fè w travay kòm asistan enfimyè san pwogram sa a?", "Pa plis pase 4 mwa", "Jiska 1 an", "Jiska 2 zan", "Toutotan yon enfimyè ap gade w", "Yon etablisman pa ka fè yon moun travay kòm asistan enfimyè plis pase 4 mwa si l poko fini yon pwogram fòmasyon ak evalyasyon ki apwouve."], ["A nursing home hires you before you finish your training program. How long can it use you as a nurse aide without that program?", "No more than 4 months", "Up to 1 year", "Up to 2 years", "As long as a nurse watches you", "A facility may not use someone as a nurse aide for more than 4 months unless they completed an approved training and competency program."]], ["n209", 2, ["HIPAA", "HIPAA"], ["Kiyès nan sa yo ou dwe kenbe konfidansyèl?", "Sèlman dyagnostik medikal rezidan an", "Sèlman sa ki ekri nan dosye a", "Plan swen, dosye ak rapò chanjman ekip", "Anyen, si rezidan an se yon moun tout moun konnen", "HIPAA pwoteje tout enfòmasyon sou swen yon rezidan, ansanm ak plan swen, dosye ak rapò chanjman ekip."], ["Which of these must you keep confidential?", "Only the resident's medical diagnosis", "Only what is written in the chart", "Care plans, records and shift reports", "Nothing, if the resident is a public figure", "HIPAA protects all information about a resident's care, including care plans, records and shift reports."]], ["n210", 3, ["nonverbal communication", "kominikasyon san pawòl"], ["Ou di yon rezidan «Pran tan w», pandan w ap soupire epi gade mont ou. Ki mesaj rezidan an gen plis chans pou l resevwa?", "Ke w kalm epi w gen pasyans", "Anyen; se pawòl sèlman ki konte", "Ke w vle pale pi lontan", "Ke w prese", "Jès kò ak ton vwa ka di plis pase pawòl. Fè aksyon w dakò ak sa w di."], ["You tell a resident, \"Take your time,\" while sighing and looking at your watch. What message does the resident most likely get?", "That you are calm and patient", "Nothing; only words matter", "That you want to talk longer", "That you are in a hurry", "Body language and tone of voice can say more than words. Make your actions match what you say."]], ["n211", 0, ["jargon", "mo medikal"], ["Ou bezwen eksplike yon swen bay yon rezidan. Kisa ki pi bon?", "Sèvi ak mo senp, mo tout jou", "Sèvi ak mo medikal ki nan dosye a", "Pale vit pou sa pa pran tan", "Eksplike sèlman bay fanmi an", "Mo medikal yo bloke kominikasyon. Sèvi ak mo rezidan an konprann."], ["You need to explain a care task to a resident. What is best?", "Use plain, everyday words", "Use the medical terms from the chart", "Speak quickly so it does not take long", "Explain only to the family", "Medical jargon is a barrier to communication. Use common words the resident understands."]], ["n212", 2, ["barrier", "obstak"], ["Ou vle pale ak yon rezidan, men televizyon an fò. Kisa ou fè?", "Pale pi fò pase televizyon an", "Etenn televizyon an san mande", "Mande si w ka bese l, apre sa pale", "Tounen yon lòt jou", "Bri se yon obstak. Diminye l, epi respekte chwa rezidan an lè w mande anvan."], ["You want to talk with a resident, but the TV is loud. What do you do?", "Talk louder than the TV", "Turn the TV off without asking", "Ask if you may turn it down, then talk", "Come back another day", "Noise is a barrier. Reduce it, and respect the resident's choice by asking first."]], ["n213", 1, ["choice", "chwa"], ["Yon rezidan konfonn. Ki kesyon sou manje midi ki pi bon?", "Kisa w ta renmen manje jodi a?", "Ou ta renmen soup oswa sandwich?", "Poukisa w pa t manje maten an?", "Ou sonje sa w te manje yè?", "Yon chwa senp ant de bagay pi fasil pou yon moun ki konfonn pase yon kesyon ouvè."], ["A resident is confused. Which question about lunch works best?", "What would you like to eat today?", "Would you like soup or a sandwich?", "Why didn't you eat breakfast?", "Do you remember what you ate yesterday?", "A simple choice between two options is easier for a confused person than an open question."]], ["n214", 1, ["confidentiality", "konfidansyalite"], ["Pitit gason yon rezidan mande w kite l li dosye manman l. Kisa ou fè?", "Kite l li l, paske se fanmi l ye", "Avèk politès, voye demann li bay enfimyè a", "Di l sa ki ladan l jan w sonje l", "Montre l sèlman paj siy vital yo", "Dosye a konfidansyèl, se sèlman moun ki dirèkteman nan swen an ki ka wè l. Se enfimyè a ki okipe demann pou wè l."], ["A resident's son asks you to let him read his mother's chart. What do you do?", "Let him read it, because he is family", "Politely refer his request to the nurse", "Tell him what is in it from memory", "Show him only the vital signs page", "The chart is confidential and is shared only with people directly involved in care. The nurse handles requests to see it."]], ["n215", 3, ["medication", "medikaman"], ["Ou se yon CNA ki pa gen sètifika asistan medikaman. Yon enfimyè ki okipe anpil mande w bay yon rezidan grenn li. Kisa ou fè?", "Bay yo, paske se enfimyè a ki mande w", "Bay yo sèlman si rezidan an dakò", "Mande yon lòt CNA bay yo", "Eksplike ou pa gen sètifika pou bay medikaman", "Nan Massachusetts, se sèlman yon CNA ki gen sètifika Asistan Medikaman ki ka bay kèk medikaman, anba siveyans. San li, bay medikaman pa nan limit travay ou."], ["You are a CNA without medication aide certification. A busy nurse asks you to give a resident her pills. What do you do?", "Give them, since the nurse asked you to", "Give them only if the resident agrees", "Ask another CNA to give them", "Explain that you are not certified to give medications", "In Massachusetts, only a CNA with Certified Medication Aide certification may give certain medications, under supervision. Without it, giving medications is outside your scope."]], ["n216", 2, ["activities of daily living (ADLs)", "aktivite lavi chak jou (ADL)"], ["Ki wòl prensipal yon asistan enfimyè nan ekip swen an?", "Deside ki tretman yon rezidan bezwen", "Ekri epi mete plan swen an ajou", "Ede ak aktivite lavi chak jou epi rapòte chanjman bay enfimyè a", "Eksplike rezilta tès yo bay rezidan yo", "Asistan enfimyè fè travay yo ba yo, tankou ede ak ADL, epi yo rapòte nenpòt chanjman nan eta yon rezidan. Tretman ak plan swen se travay pèsonèl ki gen lisans."], ["What is the main role of a nurse aide on the care team?", "Deciding which treatments a resident needs", "Writing and updating the care plan", "Helping with daily living and reporting changes to the nurse", "Explaining test results to residents", "Nurse aides do assigned tasks such as helping with ADLs, and report any change in a resident's condition. Treatments and care plans belong to licensed staff."]], ["n217", 0, ["mandated reporter", "moun lalwa oblije rapòte"], ["Ou wè yon lòt asistan kenbe bra yon rezidan fò epi pouse l sou yon chèz. Kisa ou fè?", "Asire w rezidan an an sekirite epi rapòte sa bay enfimyè a touswit", "Pale ak asistan an an prive nan fen ekip la", "Rapòte l sèlman si rezidan an gen yon mak", "Tann pou w wè si sa ap rive ankò", "Lalwa oblije w rapòte. Rapòte nenpòt siy abi bay enfimyè a touswit, epi rete ak rezidan an jiskaske l an sekirite."], ["You see another aide grab a resident's arm hard and shove her into a chair. What do you do?", "Make sure the resident is safe and report it to the nurse right away", "Talk to the aide privately at the end of the shift", "Report it only if the resident has a bruise", "Wait to see if it happens again", "You are a mandated reporter. Report any sign of abuse to the nurse right away, and stay with the resident until she is safe."]], ["n218", 1, ["care plan", "plan swen"], ["Plan swen an di yon rezidan mache ak yon wòlkè (walker). Ou an reta. Kisa ou fè?", "Pouse l nan yon chèz woulant pou w genyen tan", "Ede l mache ak wòlkè a jan plan swen an di", "Kite l mache san wòlkè a si l sanble l fèm", "Sote pwomnad li jodi a epi di pwochen ekip la", "Swiv plan swen an. Si w panse li ta dwe chanje, di enfimyè a. Pa chanje l poukont ou."], ["The care plan says a resident walks with a walker. You are running late. What do you do?", "Push him in a wheelchair to save time", "Help him walk with the walker as the care plan says", "Let him walk without the walker if he seems steady", "Skip his walk today and tell the next shift", "Follow the care plan. If you think it should change, tell the nurse. Do not change it yourself."]], ["n219", 2, ["shift report", "rapò chanjman ekip"], ["Pandan w ap soti nan fen ekip ou, ou sonje yon rezidan te di w pwatrin li te sere. Ou pa t rapòte l. Kisa ou fè?", "Ekri l sou yon papye epi kite l nan biwo enfimyè yo", "Rapòte l nan kòmansman pwochen ekip ou", "Retounen di enfimyè a anvan w ale", "Mande yon kolèg pale de li si l sonje", "Chanjman yo dwe rive jwenn enfimyè a san reta, sitou nan fen yon ekip. Pwatrin sere pa ka tann yon papye oswa pwochen ekip la."], ["As you are leaving at the end of your shift, you remember a resident told you her chest felt tight. You did not report it. What do you do?", "Write it on a note and leave it at the nurses' station", "Report it at the start of your next shift", "Go back and tell the nurse before you leave", "Ask a coworker to mention it if she remembers", "Changes must reach the nurse in a timely way, especially at the end of a shift. Chest tightness cannot wait for a note or the next shift."]], ["n220", 0, ["personal care", "swen pèsonèl"], ["Ki travay ki fè pati travay yon asistan enfimyè?", "Ede yon rezidan bwose dan l", "Bay yon rezidan yon piki ensilin", "Mete yon sond pipi", "Chanje yon pansman esteril sou yon blesi", "Swen bouch se youn nan konpetans swen pèsonèl nan fòmasyon asistan enfimyè. Piki, sond ak pansman esteril se travay enfimyè ki gen lisans."], ["Which task is part of a nurse aide's job?", "Helping a resident brush her teeth", "Giving a resident an insulin injection", "Inserting a urinary catheter", "Changing a sterile wound dressing", "Mouth care is one of the personal care skills in nurse aide training. Injections, catheters and sterile dressings are licensed nursing tasks."]], ["n221", 3, ["diagnosis", "dyagnostik"], ["Yon rezidan mande w: «Kisa doktè a jwenn nan radyografi m nan?» Ou pa konnen. Kisa ou fè?", "Di l se pwobableman anyen grav", "Gade nan dosye l epi li l pou li", "Di l li pa bezwen konnen", "Di enfimyè a pou yon moun ka swiv sa avè l", "Rezidan yo gen dwa konnen eta sante yo, men se pèsonèl ki gen lisans ki eksplike rezilta tès. Rapòte kesyon ou pa ka reponn bay enfimyè a."], ["A resident asks you, “What did the doctor find on my X-ray?” You do not know. What do you do?", "Tell him it is probably nothing serious", "Look in his chart and read it to him", "Tell him he does not need to know", "Tell the nurse so someone can follow up with him", "Residents have the right to know their health status, but test results are explained by licensed staff. Report questions you cannot answer to the nurse."]], ["n222", 2, ["social media", "rezo sosyal"], ["Yon rezidan fè yon bagay ki komik. Yon kolèg vle filme l pou rezo sosyal san montre figi l. Kisa ki vre?", "Sa bon si figi l kache", "Sa bon si kont lan prive", "Pa dwe fè l: sa kraze vi prive l, epi yon videyo ki rabese l se abi", "Sa bon si fanmi rezidan an ri lè l wè l", "Enfòmasyon ak imaj rezidan yo rete prive. Règ federal yo konsidere foto oswa anrejistreman ki rabese oswa imilye yon rezidan kòm abi mantal."], ["A resident does something funny. A coworker wants to film it for social media without showing her face. What is true?", "It is fine if her face is hidden", "It is fine if the account is private", "It must not be done: it breaks privacy, and a demeaning video is abuse", "It is fine if the resident's family laughs at it", "Resident information and images stay private. Federal rules treat photos or recordings that demean or humiliate a resident as mental abuse."]], ["n223", 1, ["supervision", "siveyans"], ["Kiyès ki dirije epi sipèvize travay asistan enfimyè a nan yon mezon retrèt?", "Fanmi rezidan an", "Yon enfimyè ki gen lisans, tankou yon RN", "Asistan ki gen plis eksperyans nan inite a", "Chak rezidan, pou pwòp swen pa yo", "Yon RN bay asistan enfimyè a travay pou l fè, epi ou dwe toujou gen yon RN sipèvizè pou w poze kesyon."], ["Who directs and supervises the nurse aide's work in a nursing home?", "The resident's family", "A licensed nurse, such as an RN", "The most experienced aide on the unit", "Each resident, for their own care", "An RN assigns or delegates tasks to the nurse aide, and you should always have an RN supervisor to go to with questions."]], ["n224", 3, ["scope of practice", "limit travay ou"], ["Pitit fi yon rezidan mande w chanje pansman sou janm manman l. Sa pa nan plan swen an, epi ou pa t janm aprann fè l. Kisa ou fè?", "Fè l avèk prekosyon, paske se fanmi an ki mande", "Fè l jis fwa sa a sèlman", "Mande pitit fi a fè l poukont li", "Eksplike ou pa kapab, epi di enfimyè a sou demann lan", "Fè sèlman travay ki nan plan swen an ou te aprann fè. Limit travay ou an premye: si yon travay depase l, se enfimyè a ki okipe demann lan."], ["A resident's daughter asks you to change the dressing on her mother's leg. It is not in the care plan, and you were never trained to do it. What do you do?", "Do it carefully, since the family asked", "Do it this one time only", "Ask the daughter to do it herself", "Explain you cannot, and tell the nurse about the request", "Do only tasks in the care plan that you were trained for. Scope comes first: if a task is outside it, the nurse handles the request."]], ["n225", 1, ["de-escalate", "kalme sitiyasyon an"], ["Yon rezidan ap rele di manje maten l toujou frèt. Ki pi bon repons lan?", "Eksplike fèm ke kizin nan pa travay ou", "Koute l kalm, san diskite, nan yon kote trankil", "Ale epi tounen lè l kalme", "Di l lòt rezidan yo pa plenyen", "Koute san kritike, pa defann tèt ou, epi kenbe bagay yo kalm. Apre sa, transmèt pwoblèm nan pou yo ka ranje l."], ["A resident is shouting that his breakfast is always cold. What is the best response?", "Explain firmly that the kitchen is not your job", "Listen calmly, without arguing, in a quiet setting", "Leave and come back when he has calmed down", "Tell him other residents are not complaining", "Listen without criticizing, do not get defensive, and keep things calm. Then pass the concern on so it can be fixed."]], ["n226", 2, ["right to refuse", "dwa pou refize"], ["Ou pral bay yon rezidan yon beny nan kabann. Kisa ou fè anvan w kòmanse?", "Kòmanse touswit pou dlo a pa frèt", "Eksplike sèlman si l mande sa w ap fè", "Eksplike sa w pral fè pou l ka poze kesyon oswa di non", "Di l se yon lòd, kidonk fòk li fèt", "Lè w eksplike anvan, rezidan an ka poze kesyon oswa refize. Rezidan yo gen dwa refize swen."], ["You are about to give a resident a bed bath. What do you do before you start?", "Start right away so the water stays warm", "Explain only if she asks what you are doing", "Explain what you will do so she can ask questions or say no", "Tell her the bath is ordered, so it must be done", "Explaining first lets the resident ask questions or decline. Residents have the right to refuse care."]], ["n227", 0, ["aphasia", "afazi"], ["Apre yon atak serebral, yon rezidan gen afazi. Li gen pwoblèm pou jwenn mo lè l ap pale avè w. Kisa ki ede plis?", "Ba l anpil tan, epi kite l lonje dwèt oswa fè jès", "Fini fraz li yo pou l pa fache", "Korije chak mo li di mal", "Pale pi fò epi bay eksplikasyon ki pi long", "Ak afazi, bay anpil tan, sèvi ak fraz kout e senp, ankouraje nenpòt fason pou kominike, epi pa korije jan moun nan pale."], ["After a stroke, a resident has aphasia. He struggles to find words when he talks to you. What helps most?", "Give him plenty of time, and let him point or gesture", "Finish his sentences so he does not get frustrated", "Correct each word he says wrong", "Speak louder and use longer explanations", "With aphasia, give plenty of time, use short simple sentences, encourage any way of communicating, and do not correct the person's speech."]], ["n228", 3, ["active listening", "koute aktivman"], ["Yon rezidan kòmanse di w li enkyete pou mari l ki lakay. Ou gen lòt travay k ap tann. Kisa ki pi bon?", "Kontinye travay epi di «mm-hm» de tan zan tan", "Di l pa enkyete, apre sa chanje sijè", "Di l pale ak travayè sosyal la pito", "Kanpe, gade l an fas, epi montre ak pawòl ak jès kò ou ke w ap koute", "Koute aktivman vle di montre, ak pawòl ak jès kò, ke sa enterese w. Bay rezidan an tout atansyon w, epi rapòte nenpòt enkyetid ki bezwen swivi."], ["A resident starts telling you she is worried about her husband at home. You have other tasks waiting. What is best?", "Keep working and say “mm-hm” now and then", "Tell her not to worry, then change the subject", "Tell her to talk to the social worker instead", "Stop, face her, and show with words and body language that you are listening", "Active listening means showing, with words and body language, that you are interested. Give the resident your full attention, and report any concern that needs follow-up."]], ["n229", 2, ["hearing aid", "aparèy pou tande"], ["Yon rezidan mete aparèy pou tande, men yo sou ti tab bò kabann li. Ou bezwen eksplike swen li. Kisa ou fè an premye?", "Pale fò depi nan pòt la", "Ekri tout bagay olye pale", "Ede l mete aparèy li yo, apre sa gade l an fas epi pale", "Eksplike kanmarad chanm li pou l ka di l", "Ede rezidan yo sèvi ak aparèy yo, tankou aparèy pou tande, anvan w pale. Apre sa gade yo an fas epi pale klè."], ["A resident wears hearing aids, but they are on her nightstand. You need to explain her care. What do you do first?", "Speak loudly from the doorway", "Write everything down instead of talking", "Help her put her hearing aids in, then face her and speak", "Explain to her roommate so she can pass it on", "Help residents use their devices, such as hearing aids, before you talk. Then face them and speak clearly."]], ["n230", 1, ["low vision", "pa wè byen"], ["Yon rezidan avèg. Kisa ou fè lè w antre nan chanm li?", "Touche zepòl li an premye pou l konnen ou la", "Di kiyès ou ye pandan w ap antre", "Travay san bri pou w pa fè l sezi", "Tann li pale an premye", "Di kiyès ou ye lè w antre kote moun nan ye, pou yon moun ki pa wè konnen kiyès ki la."], ["A resident is blind. What do you do when you enter his room?", "Touch his shoulder first so he knows you are there", "Say who you are as you come in", "Work quietly so you do not startle him", "Wait for him to speak first", "Identify yourself when you enter the person's space, so a person who cannot see knows who is there."]]]},
{"ch": 3, "bp": ["Egzamen ekri MA: Sante mantal (4 kesyon sou 60) ak Swen moun ki gen pwoblèm memwa oswa sans (3).", "MA written exam: Mental Health (4 of 60 questions) and Care Impaired (3)."], "title": ["Sante mantal ak demans", "Mental health and dementia"], "src": ["S1", "S23"], "sections": [{"h": ["Depresyon ak enkyetid", "Depression and anxiety"], "src": ["S1", "S23"], "b": [["li", "Siy depresyon: moral ki tris, chimerik oswa vid, pa enterese ankò nan bagay moun nan te renmen, pa dòmi byen, chanjman nan apeti oswa pwa, fatig, dekourajman, ak pa okipe pwòpte l.", "Signs of depression: a sad, irritable or empty mood, loss of interest in things the person enjoyed, poor sleep, changes in appetite or weight, tiredness, hopelessness, and poor hygiene."], ["li", "Rapòte chanjman nan moral bay enfimyè a. Si yon rezidan pale de mouri oswa fè tèt li mal, di enfimyè a touswit.", "Report changes in mood or outlook to the nurse. If a resident talks about dying or hurting themselves, tell the nurse right away."], ["li", "Enkyetid ka lakòz ajitasyon, chimerik, misk ki rèd ak move dòmi. Yon atak panik se yon gwo laperèz ki rive toudenkou, souvan ak swe, tranble ak souf kout.", "Anxiety can cause restlessness, irritability, tense muscles and poor sleep. A panic attack is sudden, intense fear, often with sweating, trembling and shortness of breath."], ["li", "Bay rezidan an tan pou l pale, kenbe menm woutin yo, epi pa pran konpòtman yo pou tèt ou.", "Allow time for the resident to talk, keep routines predictable, and do not take behaviors personally."], ["li", "Lè yon rezidan pale sou santiman tristès oswa dezespwa, koute l epi kite l pale.", "When a resident shares sad or hopeless feelings, listen and let them talk."], ["li", "Remake epi felisite efò yon rezidan ki deprime fè pou l patisipe nan swen li oswa pou l pase tan ak lòt moun.", "Notice and praise a depressed resident's efforts to take part in their care or to spend time with others."], ["li", "Si yon rezidan pè oswa fache pandan swen an, kanpe. Pale dousman ak yon vwa ba, eksplike chak etap, epi pran yon poz si sa nesesè.", "If a resident becomes frightened or upset during care, stop. Speak slowly in a soft voice, explain each step, and take a break if needed."], ["li", "Si yon rezidan ajite epi l refize swen, kenbe tout moun an sekirite epi fè sèlman sa ki vrèman nesesè kounye a. Eseye vire atansyon l sou yon lòt aktivite, epi eseye swen an ankò pita.", "If a resident becomes agitated and refuses care, keep everyone safe and do only what is truly needed right now. Try to redirect them to another activity, and try the care again later."]]}, {"h": ["Sa pou w konnen sou demans", "Dementia basics"], "src": ["S1"], "b": [["li", "Maladi Alzheimer se kalite demans ki pi komen. Pa gen gerizon.", "Alzheimer's disease is the most common type of dementia. There is no cure."], ["li", "Konpòtman yo se siy maladi a, moun nan pa fè yo espre. Pa pran yo pou tèt ou.", "Behaviors are symptoms of the disease, not done on purpose. Do not take them personally."], ["li", "Ajitasyon ki fèk parèt oswa ki vin pi grav ka soti nan doulè, yon enfeksyon tankou enfeksyon nan pipi, grangou, swaf, fatig, bri oswa twòp kesyon. Chèche kòz la epi rapòte l.", "New or worse agitation can come from pain, an infection such as a UTI, hunger, thirst, tiredness, noise or too many questions. Look for the cause and report it."]]}, {"h": ["Pale ak yon moun ki gen demans", "Communicating with a person with dementia"], "src": ["S1"], "b": [["li", "Sèvi ak mo senp, bay youn oswa de chwa, epi bay tan pou l reponn. Montre sa w vle di ak men w.", "Use simple words, offer one or two choices, and give time to answer. Show or gesture what you mean."], ["li", "Validasyon: aksepte reyalite moun nan ap viv la. Pa diskite ni eseye korije l. Reponn a santiman l, apre sa vire atansyon l dousman.", "Validation: accept the reality the person is living in. Do not argue or try to correct them. Respond to the feeling, then gently redirect."], ["li", "Si moun nan wè oswa tande bagay ki pa la, pa diskite. Rasire l, chanje lide l, epi di enfimyè a.", "If the person sees or hears things that are not there, do not argue. Reassure them, distract them, and tell the nurse."]]}, {"h": ["Konfizyon aswè ak moun ki mache san rete", "Sundowning and wandering"], "src": ["S1"], "b": [["li", "Konfizyon aswè (sundowning) se ajitasyon oswa konfizyon ki kòmanse oswa ki vin pi grav nan apremidi ak aswè, lè limyè jou a ap bese.", "Sundowning is restlessness, agitation or confusion that starts or gets worse in the late afternoon and evening, as daylight fades."], ["li", "Pou ede: limyè jou nan maten, aswè trankil, fèmen rido yo lè solèy ap kouche, mwens bri ak mwens vizitè, epi pa gen kafeyin ta nan jounen an.", "To help: daylight in the morning, quiet early evenings, close the curtains at dusk, less noise and fewer visitors, and no caffeine late in the day."], ["li", "Moun nan mache san rete lè l pa konn kote l ye. Pou diminye risk la: fè egzèsis regilye ak ti travay senp tankou pliye sèvyèt. Plan swen an ka gen yon braslè alam.", "Wandering happens when the person is confused about where they are. To lower the risk: regular exercise and simple tasks such as folding towels. A wander alarm bracelet may be in the care plan."]]}], "terms": [["depression", "depresyon"], ["anxiety", "enkyetid"], ["dementia", "demans"], ["validation", "validasyon"], ["redirect", "vire atansyon"], ["sundowning", "konfizyon aswè"], ["wandering", "mache san rete"], ["hallucination", "alisinasyon"]], "qs": [["n301", 3, ["depression", "depresyon"], ["Kiyès nan sa yo ki ka yon siy depresyon nan yon rezidan?", "Mande yon dezyèm plat nan manje aswè", "Patisipe nan tout aktivite gwoup", "Pale anpil ak vizitè", "Pa enterese ankò nan bagay li te konn renmen", "Pa enterese ankò, chanjman nan dòmi ak apeti, fatig ak dekourajman ka siy depresyon. Rapòte yo bay enfimyè a."], ["Which of these can be a sign of depression in a resident?", "Asking for a second helping at dinner", "Joining every group activity", "Talking a lot with visitors", "Losing interest in things they used to enjoy", "Loss of interest, changes in sleep and appetite, tiredness and hopelessness can be signs of depression. Report them to the nurse."]], ["n302", 1, ["report", "rapòte"], ["Pandan w ap ede yon rezidan abiye, li di: «Mwen pa vle viv ankò.» Kisa ou fè?", "Chanje sijè a pou fè l kontan", "Di enfimyè a touswit", "Ekri l nan nòt ou nan fen woulman an", "Kenbe l sekrè paske li fè w konfyans", "Lè yon moun pale de mouri oswa fè tèt li mal, fòk ou rapòte l bay enfimyè a touswit. Rete janti, koute l, epi swiv règ etablisman an."], ["While you help a resident dress, she says, \"I don't want to live anymore.\" What do you do?", "Change the subject to cheer her up", "Tell the nurse right away", "Write it in your notes at the end of the shift", "Keep it secret because she trusts you", "Talk about dying or self-harm must be reported to the nurse right away. Stay kind and listen, and follow your facility's policy."]], ["n303", 0, ["panic attack", "atak panik"], ["Yon rezidan santi l pè anpil toudenkou, l ap swe, l ap tranble, epi li di li pa ka respire. Kisa ou fè?", "Rete avè l epi rele enfimyè a", "Di l se nan tèt li sa ye", "Kite l poukont li pou l ka kalme l", "Ba l yon grenn ki nan tiwa l", "Sa ka yon atak panik, men souf kout ka yon ijans medikal tou. Rete avè l epi rele enfimyè a."], ["A resident suddenly feels terrified, is sweating and trembling, and says he can't catch his breath. What do you do?", "Stay with him and get the nurse", "Tell him it is all in his head", "Leave him alone so he can calm down", "Give him a pill from his drawer", "This may be a panic attack, but shortness of breath can also be a medical emergency. Stay with him and get the nurse."]], ["n304", 2, ["routine", "woutin"], ["Yon rezidan ki gen enkyetid fache lè jounen l chanje. Kisa ki ede plis?", "Fè l sipriz ak nouvo aktivite", "Di l sispann enkyete l", "Kenbe menm woutin nan epi ba l tan pou l pale", "Chanje moun k ap okipe l chak jou", "Woutin ki pa chanje, menm moun k ap okipe l, ak tan pou pale ede rezidan ki gen enkyetid santi yo an sekirite."], ["A resident with anxiety gets upset when her day changes. What helps most?", "Surprise her with new activities", "Tell her to stop worrying", "Keep a predictable routine and give her time to talk", "Change her caregivers every day", "Predictable routines, consistent staff and time to talk help residents with anxiety feel safe."]], ["n305", 1, ["Alzheimer's disease", "maladi Alzheimer"], ["Ki kalite demans ki pi komen?", "Delirium", "Maladi Alzheimer", "Depresyon", "Maladi Parkinson", "Maladi Alzheimer lakòz pifò ka demans. Pa gen gerizon, epi li vin pi grav ak tan."], ["What is the most common type of dementia?", "Delirium", "Alzheimer's disease", "Depression", "Parkinson's disease", "Alzheimer's disease causes most cases of dementia. There is no cure, and it gets worse over time."]], ["n306", 3, ["agitation", "ajitasyon"], ["Yon rezidan ki gen demans pi ajite jodi a pase dabitid. Kisa pou w panse an premye?", "Ke l fè l espre", "Ke yo bezwen mare l", "Ke pa gen anyen pou fè", "Yon kòz tankou doulè, enfeksyon, grangou oswa swaf, epi rapòte l", "Ajitasyon ki fèk parèt souvan gen yon kòz moun nan pa ka eksplike, tankou doulè oswa enfeksyon nan pipi. Chèche l epi rapòte l."], ["A resident with dementia is much more agitated today than usual. What should you think about first?", "That he is doing it on purpose", "That he needs to be restrained", "That nothing can be done", "A cause such as pain, infection, hunger or thirst, and report it", "New agitation often has a cause the person cannot explain, such as pain or a urinary infection. Look for it and report it."]], ["n307", 0, ["validation", "validasyon"], ["Yon rezidan ki gen demans di li dwe al lakay li pou l bay pitit li manje. Pitit li yo se granmoun. Ki pi bon repons lan?", "«Ou renmen pitit ou anpil. Pale m de yo,» apre sa ofri l yon aktivite", "«Pitit ou yo granmoun. Se isit ou rete kounye a.»", "«Sa pa vre, e ou konnen sa.»", "Pa okipe l jiskaske l rete", "Validasyon aksepte reyalite l epi reponn a santiman ki dèyè l. Korije l ka fè l fache. Apre sa vire atansyon l dousman."], ["A resident with dementia says she must go home to feed her children. Her children are adults. What is the best response?", "\"You really care about your children. Tell me about them,\" then offer an activity", "\"Your children are grown up. You live here now.\"", "\"That's not true, and you know it.\"", "Ignore her until she stops", "Validation accepts her reality and answers the feeling behind it. Correcting her can upset her. Then gently redirect."]], ["n308", 2, ["hallucination", "alisinasyon"], ["Yon rezidan ki gen demans montre mi a epi di gen ensèk k ap mache sou li. Pa gen anyen. Kisa ou fè?", "Di l fèm pa gen ensèk", "Flite mi a pou montre l", "Rasire l, chanje lide l, epi di enfimyè a", "Ri pou l ka detann li", "Pa diskite sou sa yon moun wè oswa tande. Rasire l, chanje lide l, epi rapòte l."], ["A resident with dementia points at the wall and says there are bugs crawling on it. There are none. What do you do?", "Tell him firmly that there are no bugs", "Spray the wall to show him", "Reassure him, distract him, and tell the nurse", "Laugh so he relaxes", "Do not argue about what a person sees or hears. Offer reassurance and distraction, and report it."]], ["n309", 1, ["sundowning", "konfizyon aswè"], ["Kisa konfizyon aswè (sundowning) ye?", "Dòmi twòp lajounen", "Konfizyon oswa ajitasyon ki vin pi grav nan apremidi ak aswè", "Boule solèy paske l te chita deyò", "Leve bonè anpil chak maten", "Konfizyon aswè se ajitasyon oswa konfizyon ki kòmanse oswa ki vin pi grav lè limyè jou a ap bese."], ["What is sundowning?", "Sleeping too much during the day", "Confusion or agitation that gets worse in the late afternoon and evening", "A sunburn from sitting outside", "Waking up very early every morning", "Sundowning is restlessness, agitation or confusion that starts or worsens as daylight fades."]], ["n310", 3, ["sundowning", "konfizyon aswè"], ["Kiyès nan sa yo ki ka ede yon rezidan ki gen konfizyon aswè?", "Kafe ak manje aswè", "Yon aswè chaje, ak bri ak anpil vizitè", "Kenbe chanm nan fènwa tout jounen an", "Limyè jou nan maten ak yon aswè trankil", "Limyè jou nan maten, aswè trankil, fèmen rido lè solèy ap kouche ak pa gen kafeyin ta ka diminye konfizyon aswè."], ["Which of these can help a resident who has sundowning?", "Coffee with dinner", "A busy, noisy evening with many visitors", "Keeping the room dark all day", "Morning daylight and a quiet early evening", "Daylight in the morning, quiet evenings, closing curtains at dusk and no late caffeine can reduce sundowning."]], ["n311", 0, ["wandering", "mache san rete"], ["Yon rezidan ki gen demans konn mache nan koridò yo epi eseye soti nan inite a. Kisa ki ka diminye risk la?", "Egzèsis regilye ak ti travay senp, tankou pliye sèvyèt", "Kenbe l nan kabann tout jounen an", "Mare l sou yon chèz", "Retire soulye l", "Aktivite ak travay ki okipe l diminye mache san rete. Plan swen an ka gen yon braslè alam. Mare l pa solisyon an."], ["A resident with dementia often walks the halls and tries to leave the unit. What can lower the risk?", "Regular exercise and simple tasks, such as folding towels", "Keeping him in bed all day", "Tying him to a chair", "Taking away his shoes", "Activity and engaging tasks reduce wandering. A wander alarm bracelet may be in the care plan. Restraints are not the answer."]], ["n312", 2, ["feelings", "santiman"], ["Yon rezidan ap kriye. Li di: «Mwen pa itil ankò. Mwen pa ka fè anyen.» Ki pi bon repons lan?", "«Pa di sa. Gade bon bò bagay yo.»", "«Tout moun santi konsa nan laj ou.»", "«Sa sanble difisil. Ou ta renmen rakonte m sa?»", "«M ap mande enfimyè a yon bagay pou fè w kontan.»", "Lè yon rezidan pale sou santiman tristès oswa dezespwa, koute l epi kite l pale. Si w meprize santiman yo, ou fèmen konvèsasyon an. Rapòte yon chanjman nan atitid li bay enfimyè a."], ["A resident is crying. She says, “I'm useless now. I can't do anything.” What is the best response?", "“Don't say that. Look on the bright side.”", "“Everyone feels that way at your age.”", "“That sounds hard. Would you like to tell me about it?”", "“I'll ask the nurse for something to cheer you up.”", "When a resident shares sad or hopeless feelings, listen and let them talk. Brushing the feelings off shuts the conversation down. Report a change in mood to the nurse."]], ["n313", 0, ["reassure", "rasire"], ["Pandan yon douch, yon rezidan sanble pè toudenkou epi l pouse men w. Kisa ou fè?", "Kanpe, pale dousman ak vwa ba, epi eksplike chak etap", "Fini vit pou douch la ka fini pi vit", "Kenbe bra l pou l pa glise", "Kite l poukont li nan douch la pou l kalme", "Si yon rezidan pè pandan swen an, kanpe. Pale dousman ak yon vwa ba, eksplike chak etap, epi pran yon poz si sa nesesè. Pa janm kite l poukont li nan douch."], ["During a shower, a resident suddenly becomes frightened and pushes your hand away. What do you do?", "Stop, speak slowly and softly, and explain each step", "Finish quickly so the shower is over sooner", "Hold her arms so she does not slip", "Leave her alone in the shower to calm down", "If a resident becomes frightened during care, stop. Speak slowly in a soft voice, explain each step, and take a break if needed. Never leave her alone in the shower."]], ["n314", 3, ["encourage", "ankouraje"], ["Yon rezidan ki gen depresyon rete nan chanm li pandan plizyè semèn. Jodi a li vin manje midi nan sal manje a. Kisa ou fè?", "Pa di anyen, pou l pa santi y ap veye l", "Mande l poukisa l pa t vini depi lontan", "Di l fòk li vini chak jou kounye a", "Di l ou kontan wè l, epi felisite efò l", "Remake epi felisite efò yon rezidan ki deprime fè pou l patisipe nan swen li oswa pase tan ak lòt moun. Sa ankouraje l kontinye."], ["A resident with depression has stayed in her room for weeks. Today she comes to the dining room for lunch. What do you do?", "Say nothing, so she does not feel watched", "Ask why she stayed away for so long", "Tell her she should come every day from now on", "Tell her you are glad to see her, and praise her effort", "Notice and praise a depressed resident's efforts to take part in care or to spend time with others. It encourages her to keep going."]], ["n315", 1, ["reapproach", "eseye ankò pita"], ["Yon rezidan vin ajite epi l rele li p ap abiye. Li an sekirite sou chèz li. Kisa ki pi bon?", "Abiye l vit anvan l vin pi fache", "Vire atansyon l sou yon lòt bagay epi eseye ankò pita", "Di l fòk li abiye paske se règ la", "Rele fanmi l pou yo konvenk li", "Lè yon rezidan ajite, kenbe tout moun an sekirite epi fè sèlman sa ki vrèman nesesè kounye a. Vire atansyon l sou yon lòt aktivite epi tounen pita."], ["A resident becomes agitated and shouts that he will not get dressed. He is safe in his chair. What is best?", "Dress him quickly before he gets more upset", "Redirect him to something else and try again later", "Tell him he must get dressed because it is the rule", "Call his family to convince him", "When a resident is agitated, keep everyone safe and do only what is truly needed right now. Redirect him to another activity and reapproach later."]]]},
{"ch": 4, "bp": ["Egzamen ekri MA: Maladi yo (7 kesyon sou 60).", "MA written exam: Disease Process (7 of 60 questions)."], "title": ["Maladi ki komen", "Common diseases"], "src": ["S1"], "sections": [{"h": ["Dyabèt", "Diabetes"], "src": ["S1"], "b": [["li", "Sik ba: konfizyon oswa chimerik, tranble, po frèt ak mouye, swe, grangou, enkyetid. Rapòte l bay enfimyè a touswit.", "Low blood sugar: confusion or irritability, shakiness, cold clammy skin, sweating, hunger, anxiety. Report it to the nurse immediately."], ["li", "Sik wo: pipi souvan, plis swaf ak grangou, souf ki gen sant fwi, po cho ak sèk, respire vit ak fon. Rapòte l bay enfimyè a touswit.", "High blood sugar: frequent urination, more thirst and hunger, fruity breath, warm dry skin, fast deep breathing. Report it to the nurse immediately."], ["li", "Tcheke pye yo chak jou, ansanm ak anba pye ak ant zòtèy. Pa koupe zong yon rezidan ki gen dyabèt.", "Check the feet every day, including the soles and between the toes. Do not trim the nails of a resident with diabetes."]]}, {"h": ["Kè fèb (ensifizans kadyak)", "Heart failure"], "src": ["S1"], "b": [["li", "Nan ensifizans kadyak, misk kè a twò fèb pou l ponpe ase san.", "In heart failure, the heart muscle is too weak to pump enough blood."], ["li", "Rapòte anflamasyon ki ap ogmante, souf kout, po ki vin ble, oswa pwa ki monte vit (plis pase 2 a 3 liv nan 24 èdtan).", "Report increasing swelling, shortness of breath, bluish skin, or rapid weight gain (more than 2 to 3 pounds in 24 hours)."], ["li", "Peze rezidan an jan plan swen an di, swiv restriksyon likid, epi mezire sa k antre ak sa k soti.", "Weigh the resident as the care plan says, follow any fluid restriction, and measure intake and output."]]}, {"h": ["Maladi poumon kwonik (COPD)", "COPD"], "src": ["S1"], "b": [["li", "COPD se yon enflamasyon nan poumon ki dire lontan, souvan akoz sigarèt.", "COPD is long-term inflammation of the lungs, often caused by smoking."], ["li", "Rapòte souf kout, difikilte pou respire, toudi, konfizyon oswa koulè ble touswit.", "Report shortness of breath, labored breathing, dizziness, confusion or blue color right away."], ["li", "Ankouraje oksijèn sèlman jan yo preskri l. Pa chanje reglaj oksijèn nan poukont ou.", "Encourage oxygen only as prescribed. Do not change oxygen settings yourself."]]}, {"h": ["Maladi Parkinson", "Parkinson's disease"], "src": ["S1"], "b": [["li", "Parkinson lakòz mouvman ki dousman, move kowòdinasyon ak ekilib, tranbleman ak difikilte pou pale.", "Parkinson's causes slow movement, poor coordination and balance, tremors and trouble speaking."], ["li", "Veye tonbe, kenbe aparèy pou mache nan rive men l, bay plis tan pou swen chak jou, epi rapòte chanjman nan fòs oswa jan l mache.", "Watch for falls, keep walking aids within reach, allow extra time for daily care, and report changes in strength or walking."]]}, {"h": ["Atrit", "Arthritis"], "src": ["S1"], "b": [["li", "Atrit (osteoarthritis) se enflamasyon jwenti akoz plizyè ane itilizasyon.", "Osteoarthritis is joint inflammation from years of wear and tear."], ["li", "Mezi konfò nan plan swen an ka gen chalè, glas oswa chanje pozisyon. Ankouraje rezidan an rete aktif otan l kapab pou kenbe mouvman jwenti l.", "Comfort measures from the care plan may include heat, ice or repositioning. Encourage the resident to stay as active as possible to keep range of motion."]]}], "terms": [["high blood sugar (hyperglycemia)", "sik wo"], ["heart failure", "ensifizans kadyak"], ["edema", "anflamasyon (edèm)"], ["COPD", "COPD"], ["tremor", "tranbleman"], ["arthritis", "atrit"]], "qs": [["n401", 2, ["high blood sugar (hyperglycemia)", "sik wo"], ["Yon rezidan ki gen dyabèt swaf anpil, l ap pipi souvan, epi souf li gen yon sant fwi. Kisa sa ka ye?", "Sik ba", "Yon reyaksyon nòmal apre manje", "Sik wo; rapòte l touswit", "Yon grip k ap vini", "Pipi souvan, swaf, souf ak sant fwi, po cho ak sèk ak respire vit ak fon se siy sik wo. Rapòte yo bay enfimyè a touswit."], ["A resident with diabetes is very thirsty, urinating often, and has a fruity smell on his breath. What may this be?", "Low blood sugar", "A normal reaction to dinner", "High blood sugar; report it immediately", "A cold coming on", "Frequent urination, thirst, fruity breath, warm dry skin and fast deep breathing are signs of high blood sugar. Report them to the nurse immediately."]], ["n402", 0, ["weight gain", "pwa ki monte"], ["Yon rezidan ki gen ensifizans kadyak peze 3 liv plis pase yè. Kisa ou fè?", "Rapòte l bay enfimyè a", "Anyen; pwa chanje chak jou", "Ba l mwens manje", "Peze l ankò semèn pwochèn", "Pwa ki monte vit (plis pase 2 a 3 liv nan 24 èdtan) ka vle di likid ap ranmase nan kò a. Rapòte l."], ["A resident with heart failure weighs 3 pounds more than yesterday. What do you do?", "Report it to the nurse", "Nothing; weight changes every day", "Give him less food", "Weigh him again next week", "Rapid weight gain (more than 2 to 3 pounds in 24 hours) can mean fluid is building up. Report it."]], ["n403", 3, ["intake and output", "sa k antre ak sa k soti"], ["Ki travay ki souvan nan plan swen yon rezidan ki gen ensifizans kadyak?", "Plis sèl nan manje", "Kouche plat tout jounen an", "Bwè dlo otan posib", "Peze l regilyèman epi mezire sa k antre ak sa k soti", "Pwa ak mezi sa k antre ak sa k soti montre si likid ap ranmase. Swiv restriksyon likid la egzakteman."], ["Which task is often in the care plan of a resident with heart failure?", "Extra salt with meals", "Lying flat all day", "As much water as possible", "Regular weights and measuring intake and output", "Weights and intake and output show whether fluid is building up. Follow any fluid restriction exactly."]], ["n404", 1, ["cyanosis", "po ki vin ble"], ["Yon rezidan ki gen COPD ap respire difisil epi po bouch li sanble ble. Kisa ou fè?", "Monte oksijèn li", "Rapòte l bay enfimyè a touswit", "Fè l kouche plat pou l repoze", "Tann 30 minit", "Fòk ou rapòte touswit lè yon moun ap respire difisil epi l vin ble. Pa chanje reglaj oksijèn nan poukont ou."], ["A resident with COPD is breathing hard and her lips look blue. What do you do?", "Turn up her oxygen", "Report it to the nurse right away", "Have her lie flat to rest", "Wait 30 minutes", "Labored breathing and blue color must be reported right away. Do not change oxygen settings yourself."]], ["n405", 0, ["COPD", "COPD"], ["Ki kòz ki komen pou COPD?", "Fimen sigarèt", "Manje twòp sik", "Pa dòmi ase", "Bwè dlo frèt", "COPD se enflamasyon poumon ki dire lontan, souvan akoz sigarèt."], ["What is a common cause of COPD?", "Smoking", "Eating too much sugar", "Not enough sleep", "Drinking cold water", "COPD is long-term inflammation of the lungs, often caused by smoking."]], ["n406", 3, ["tremor", "tranbleman"], ["Ki siy ki komen nan maladi Parkinson?", "Lafyèv ak gratèl", "Souf ak sant fwi ak swaf", "Pwa ki monte toudenkou", "Tranbleman, mouvman dousman ak move ekilib", "Parkinson lakòz mouvman dousman, move kowòdinasyon ak ekilib, tranbleman ak pwoblèm pou pale."], ["Which signs are common in Parkinson's disease?", "Fever and rash", "Fruity breath and thirst", "Sudden weight gain", "Tremors, slow movement and poor balance", "Parkinson's causes slow movement, poor coordination and balance, tremors and speech problems."]], ["n407", 2, ["fall risk", "risk tonbe"], ["Ki pi bon fason pou w ede yon rezidan ki gen Parkinson abiye?", "Prese pou l pa fatige", "Abiye l nèt ou menm", "Ba l plis tan epi kenbe machin pou mache l nan rive men l", "Fè l kanpe san sipò", "Bay plis tan pou swen chak jou, kenbe aparèy pou mache nan rive men l, epi veye tonbe."], ["How do you best help a resident with Parkinson's disease get dressed?", "Hurry so he does not get tired", "Dress him completely yourself", "Allow extra time and keep his walker within reach", "Have him stand without support", "Allow more time for daily care, keep walking aids within reach, and watch for falls."]], ["n408", 1, ["arthritis", "atrit"], ["Yon rezidan ki gen atrit di jwenti l yo rèd. Kisa pou w ankouraje?", "Rete nan kabann jiskaske doulè a pase", "Rete aktif otan posib, jan plan swen an pèmèt", "Evite tout mouvman jwenti yo", "Pran yon grenn doulè anplis", "Rete aktif ede kenbe mouvman jwenti yo. Sèvi ak mezi konfò ki nan plan swen an, epi pa janm bay medikaman poukont ou."], ["A resident with arthritis says her joints are stiff. What should you encourage?", "Staying in bed until the pain is gone", "Staying as active as possible, as the care plan allows", "Avoiding all movement of the joints", "Taking an extra pain pill", "Staying active helps keep range of motion. Use comfort measures from the care plan, and never give medication yourself."]]]},
{"ch": 5, "bp": ["Egzamen ekri MA: yon pati nan Dwa rezidan yo (6 kesyon sou 60) ak Sekirite (6).", "MA written exam: part of Resident Rights (6 of 60 questions) and Safety (6)."], "title": ["Mare moun ak lòt solisyon", "Restraints and restraint alternatives"], "src": ["S1", "S20"], "sections": [{"h": ["Sa sa ye mare yon moun", "What a restraint is"], "src": ["S1"], "b": [["p", "Mare yon moun (restraint) se nenpòt aparèy, metòd oswa pwosesis ki anpeche moun nan bouje lib.", "A restraint is any device, method or process used to restrict a person's freedom of movement."], ["li", "Egzanp: ba kabann ki leve pou anpeche rezidan an soti nan kabann, fren chèz woulant oswa senti rezidan an pa ka lage, yon plato sou janm ki anpeche l bouje.", "Examples: side rails raised to stop the resident from getting out of bed, wheelchair brakes or a seat belt the resident cannot release, a lap tray that keeps them from moving."], ["li", "Mare ak medikaman (chemical restraint) se yon medikaman yo sèvi pou kontwole konpòtman ki pa tretman nòmal pou kondisyon moun nan.", "A chemical restraint is a drug used to control behavior that is not the standard treatment for the person's condition."]]}, {"h": ["Règ yo", "The rules"], "src": ["S20", "S1"], "b": [["li", "Rezidan yo gen dwa pou yo pa mare yo pou pinisyon oswa pou fasilite travay anplwaye yo, lè sa pa nesesè pou trete yon siy medikal.", "Residents have the right to be free from restraints used for discipline or staff convenience, and not needed to treat a medical symptom."], ["li", "Swen san mare moun se règ la. Mare yon moun se dènye solisyon, epi li bezwen yon lòd doktè. Swiv plan swen an ak règ etablisman an egzakteman.", "Restraint-free care is the standard. A restraint is a last resort and needs a provider's order. Follow the care plan and facility policy exactly."], ["li", "Pa janm kite yon senti mache sou moun nan apre yon transfè pou fasilite travay ou.", "Never leave a gait belt on after a transfer for convenience."]]}, {"h": ["Lè gen lòd pou mare yon moun", "When a restraint is ordered"], "src": ["S1"], "b": [["li", "Tcheke rezidan an souvan, jan règ etablisman an di (pi bon pratik la se omwen chak 15 minit).", "Check the resident often, as facility policy says (best practice is at least every 15 minutes)."], ["li", "Retire restraint lan chak 1 a 2 èdtan pou egzèsis mouvman ak tcheke po a. Ofri manje, likid ak twalèt, epi ekri sa.", "Remove the restraint every 1 to 2 hours for range of motion and a skin check. Offer food, fluids and toileting, and document it."], ["li", "Mare restraint lan nan kabann nan sèlman ak yon ne ki demare vit.", "Tie a restraint to the bed only with a quick-release knot."], ["li", "Danje mare moun: tonbe, toufe, blesi presyon, misk ki vin fèb, laperèz ak wont.", "Risks of restraints: falls, strangulation, pressure injuries, weak muscles, fear and humiliation."]]}, {"h": ["Lòt solisyon olye mare moun", "Alternatives to restraints"], "src": ["S1"], "b": [["li", "Anvan tout bagay, chèche kòz konpòtman an: doulè, grangou, swaf oswa bezwen al nan twalèt.", "First look for the cause of the behavior: pain, hunger, thirst or needing the toilet."], ["li", "Pou yon rezidan ki toujou ap eseye leve poukont li: ofri l al nan twalèt souvan, ede l mache, epi ba l yon bagay pou l fè. Plan swen an ka gen yon alam; asire w li mache.", "For a resident who keeps trying to get up alone: offer toileting often, help them walk, and give them something to do. An alarm may be in the care plan; make sure it works."], ["li", "Apre swen, kite kabann nan nan pozisyon ki pi ba a, ak wou yo bloke, epi bouton apèl la kote rezidan an ka rive jwenn li.", "After care, leave the bed in its lowest position with the wheels locked, and the call light within reach."]]}], "terms": [["restraint", "mare moun (restraint)"], ["chemical restraint", "mare ak medikaman"], ["quick-release knot", "ne ki demare vit"], ["restraint alternative", "lòt solisyon olye mare"]], "qs": [["n501", 3, ["restraint", "mare moun (restraint)"], ["Kiyès nan sa yo ki se yon fason pou mare moun (restraint)?", "Yon machin pou mache rezidan an sèvi lè l vle", "Linèt ak aparèy pou tande", "Yon bouton apèl nan rive men l", "Yon plato sou janm rezidan an pa ka retire ki kenbe l nan chèz la", "Nenpòt bagay ki anpeche yon moun bouje lib epi l pa ka retire l se yon restraint, tankou yon plato sou janm, yon senti oswa fren li pa ka lage."], ["Which of these is a restraint?", "A walker the resident uses when she wants", "Glasses and a hearing aid", "A call light within reach", "A lap tray the resident cannot remove that keeps her in the chair", "Anything that restricts a person's freedom of movement and that they cannot remove is a restraint, such as a lap tray, a seat belt or brakes they cannot release."]], ["n502", 0, ["restraint-free care", "swen san mare moun"], ["Inite a manke anplwaye, epi yon kòlèg vle kenbe yon rezidan mare pou l pa leve. Kisa ki kòrèk?", "Yo pa janm ka mare yon moun pou fasilite travay anplwaye yo", "Sa bon si fanmi an dakò", "Sa bon pou yon sèl woulman", "Sa bon si rezidan an konfonn", "Règ federal yo bay rezidan yo dwa pou yo pa mare yo pou pinisyon oswa pou fasilite travay. Mare moun se dènye solisyon, epi li bezwen yon lòd."], ["The unit is short-staffed, and a coworker wants to keep a resident in a restraint so she won't get up. What is correct?", "Restraints may never be used for staff convenience", "It is fine if the family agrees", "It is fine for one shift", "It is fine if the resident is confused", "Federal rules give residents the right to be free from restraints used for discipline or convenience. A restraint is a last resort and needs an order."]], ["n503", 2, ["release", "lage"], ["Gen yon lòd pou mare yon rezidan. Chak konbyen tan pou w retire l pou egzèsis mouvman ak tcheke po a?", "Yon fwa pa jou", "Sèlman lè l mande", "Chak 1 a 2 èdtan", "Chak 8 èdtan", "Retire l chak 1 a 2 èdtan pou egzèsis mouvman ak tcheke po a, epi ofri manje, likid ak twalèt. Tcheke l souvan nan mitan."], ["A resident has an ordered restraint. How often should it be removed for range of motion and a skin check?", "Once a day", "Only when she asks", "Every 1 to 2 hours", "Every 8 hours", "Remove it every 1 to 2 hours for range of motion and a skin check, and offer food, fluids and toileting. Check on her often in between."]], ["n504", 1, ["quick-release knot", "ne ki demare vit"], ["Kijan pou w mare yon restraint ki gen lòd nan kabann nan?", "Ak yon ne doub byen sere", "Ak yon ne ki demare vit", "Nan ba kabann nan pou l bouje ansanm ak ba a", "Nenpòt jan, toutotan li kenbe", "Yon ne ki demare vit ka lage rapid nan yon ijans. Swiv enstriksyon aparèy la ak règ etablisman an."], ["How should an ordered restraint be tied to the bed?", "With a tight double knot", "With a quick-release knot", "To the side rail so it moves with the rail", "Any way, as long as it holds", "A quick-release knot can be undone fast in an emergency. Follow the device instructions and facility policy."]], ["n505", 3, ["restraint alternative", "lòt solisyon olye mare"], ["Yon rezidan toujou ap eseye soti nan kabann poukont li. Ki bon lòt solisyon olye mare l?", "Leve tout ba kabann yo", "Rantre dra yo byen sere otou l", "Mande enfimyè a yon grenn pou dòmi", "Ofri l al nan twalèt souvan epi ede l mache", "Chèche poukisa l ap leve, tankou bezwen al nan twalèt. Al nan twalèt regilyèman, mache ak aktivite se lòt solisyon olye mare l."], ["A resident keeps trying to get out of bed alone. Which is a good alternative to a restraint?", "Raise all side rails", "Tuck the sheets tightly around him", "Ask the nurse for a sleeping pill", "Offer toileting often and help him walk", "Look for the reason he gets up, such as needing the toilet. Regular toileting, walking and activities are alternatives to restraints."]], ["n506", 0, ["chemical restraint", "mare ak medikaman"], ["Kisa mare ak medikaman (chemical restraint) ye?", "Yon medikaman yo sèvi pou kontwole konpòtman ki pa tretman nòmal pou kondisyon an", "Yon pwodui netwayaj yo sèvi nan chanm nan", "Yon krèm pou po sèk", "Nenpòt medikaman doktè a preskri", "Yon medikaman yo sèvi pou kontwole konpòtman oswa anpeche moun bouje, epi ki pa tretman nòmal pou kondisyon an, se yon fason pou mare moun ak medikaman."], ["What is a chemical restraint?", "A drug used to control behavior that is not standard treatment for the condition", "A cleaning product used in the room", "A cream for dry skin", "Any medicine the doctor orders", "A drug used to manage behavior or restrict movement, and that is not the standard treatment for the person's condition, is a chemical restraint."]]]},
{"ch": 6, "bp": ["Egzamen ekri MA: Kolekte done (2 kesyon sou 60); egzamen pratik la ka mande w mezire pipi.", "MA written exam: Data Collection (2 of 60 questions); the skills test can include measuring urine output."], "title": ["Mezire ak ekri", "Measuring and recording"], "src": ["S1"], "sections": [{"h": ["Likid moun nan bwè", "Fluid intake"], "src": ["S1"], "b": [["li", "Yo ekri likid an mililit (mL). Miltipliye ons yo pa 30: 1 ons = 30 mL.", "Fluids are recorded in milliliters (mL). Multiply ounces by 30: 1 ounce = 30 mL."], ["li", "Kantite ki komen: 4 ons = 120 mL, 6 ons = 180 mL, 1 tas (8 ons) = 240 mL.", "Common sizes: 4 oz = 120 mL, 6 oz = 180 mL, 1 cup (8 oz) = 240 mL."], ["li", "Tout sa ki fonn nan tanperati chanm oswa nan kò a konte kòm likid: bouyon, ti mòso glas, krèm glase, fresko, jelatin. Soup konte kòm manje.", "Anything that melts at room or body temperature counts as fluid: broth, ice chips, ice cream, popsicles, gelatin. Soup is recorded as food."], ["li", "Yo estime manje moun nan manje pa 25% ki pi pre a.", "Food intake is estimated to the nearest 25%."]]}, {"h": ["Sa k soti", "Output"], "src": ["S1"], "b": [["li", "Pipi se sa yo mezire pi souvan. Yo mezire tou likid ki nan yon aparèy drenaj.", "Urine is the output measured most often. Drainage in a drainage device is also measured."], ["li", "Yo fè total sa k antre ak sa k soti pou 24 èdtan. Total sa k antre dwe pre total sa k soti.", "Intake and output are totaled over 24 hours. Total intake should be close to total output."]]}, {"h": ["Pwa", "Weight"], "src": ["S1"], "b": [["li", "Sèvi ak menm balans lan, menm lè nan jounen an, anvan rezidan an manje oswa bwè, ak prèske menm rad.", "Use the same scale, at the same time of day, before the resident eats or drinks, with about the same clothing."], ["li", "Nan chèz woulant: peze chèz la anvan, apre sa peze rezidan an nan chèz la, epi retire pwa chèz la.", "In a wheelchair: weigh the chair first, then the resident in the chair, and subtract the chair's weight."], ["li", "Rapòte yon chanjman 3 liv nan 24 èdtan oswa 5 liv nan yon semèn bay enfimyè a touswit.", "Report a change of 3 pounds in 24 hours or 5 pounds in a week to the nurse right away."]]}, {"h": ["Wotè", "Height"], "src": ["S1"], "b": [["li", "Yo konn mezire wotè lè rezidan an fèk antre. Yon rezidan ki ka kanpe, yo mezire l kanpe.", "Height is usually measured at admission. A resident who can stand is measured standing."], ["li", "Si rezidan an pa ka kanpe, mezire l kouche nan kabann ak yon mèt riban.", "If the resident cannot stand, measure them lying in bed with a tape measure."]]}], "terms": [["intake and output (I&O)", "sa k antre ak sa k soti"], ["milliliter (mL)", "mililit (mL)"], ["ounce (oz)", "ons"], ["graduate (measuring container)", "veso pou mezire"], ["scale", "balans"]], "qs": [["n601", 2, ["milliliter (mL)", "mililit (mL)"], ["Yon rezidan bwè yon vè ji 6 ons. Konbyen mL pou w ekri?", "60 mL", "120 mL", "180 mL", "240 mL", "1 ons = 30 mL, kidonk 6 ons x 30 = 180 mL."], ["A resident drinks a 6-ounce glass of juice. How many mL do you record?", "60 mL", "120 mL", "180 mL", "240 mL", "1 ounce = 30 mL, so 6 ounces x 30 = 180 mL."]], ["n602", 0, ["intake and output (I&O)", "sa k antre ak sa k soti"], ["Yon rezidan ki sou mezi sa k antre ak sa k soti manje midi. Ki bagay ou konte kòm likid?", "Krèm glase", "Soup", "Pòmdetè kraze", "Pen", "Tout sa ki fonn nan tanperati chanm oswa nan kò a konte kòm likid, tankou krèm glase, jelatin ak ti mòso glas. Soup konte kòm manje."], ["A resident on intake and output has lunch. Which item do you count as fluid intake?", "Ice cream", "Soup", "Mashed potatoes", "Bread", "Anything that melts at room or body temperature counts as fluid, like ice cream, gelatin and ice chips. Soup is recorded as food."]], ["n603", 3, ["meal percentage", "pousantaj manje"], ["Kijan yo konn ekri kantite manje yon rezidan manje?", "Konte chak mòde", "An kalori", "Sèlman «manje» oswa «pa manje»", "An pousantaj, pa 25% ki pi pre a", "Sòf si yo di w otreman, estime manje a pa 25% ki pi pre a (egzanp 25%, 50%, 75%)."], ["How is a resident's food intake usually recorded?", "By counting every bite", "In calories", "Only as \"ate\" or \"did not eat\"", "As a percentage, to the nearest 25%", "Unless told otherwise, estimate food intake to the nearest 25% (for example 25%, 50%, 75%)."]], ["n604", 1, ["scale", "balans"], ["Pou w jwenn bon pwa, kijan pou w peze yon rezidan chak fwa?", "Sou nenpòt balans, touswit apre manje", "Menm balans, menm lè nan jounen an, anvan manje, prèske menm rad", "Ak soulye ak manto pou l rete cho", "Yon lè diferan chak jou", "Lè w kenbe menm balans, menm lè ak menm rad, ou ka konpare pwa yo, epi vrè chanjman yo parèt."], ["To get accurate weights, how should you weigh a resident each time?", "On any scale, right after a meal", "Same scale, same time of day, before eating, similar clothing", "In shoes and a coat so they stay warm", "At a different time each day", "Keeping the scale, time and clothing the same makes weights comparable, so real changes stand out."]], ["n605", 0, ["wheelchair scale", "balans chèz woulant"], ["Kijan pou w peze yon rezidan ki nan chèz woulant sou yon balans pou chèz woulant?", "Peze chèz vid la, apre sa rezidan an ladan l, epi retire pwa chèz la", "Ekri total la ak chèz la", "Devine pwa a dapre dènye fwa yo te ekri l", "Peze sèlman janm rezidan an", "Peze chèz la ak pyès li yo anvan, apre sa rezidan an nan chèz la, epi retire pwa chèz la."], ["How do you weigh a resident who uses a wheelchair on a wheelchair scale?", "Weigh the empty chair, then the resident in it, and subtract the chair", "Record the total with the chair", "Guess the weight from the last chart entry", "Weigh only the resident's legs", "Weigh the chair and its parts first, then the resident in the chair, and subtract the chair's weight."]], ["n606", 2, ["height", "wotè"], ["Yon rezidan pa ka kanpe. Kijan pou w mezire wotè l?", "Mande fanmi l ki wotè l", "Pa fè l", "Ak yon mèt riban pandan l kouche nan kabann", "Kenbe l kanpe sou mi an", "Si rezidan an pa ka kanpe, mezire l kouche nan kabann ak yon mèt riban."], ["A resident cannot stand. How do you measure her height?", "Ask her family how tall she is", "Skip it", "With a tape measure while she lies in bed", "Hold her up against the wall", "If the resident cannot stand, measure her lying in bed with a tape measure."]]]},
{"ch": 7, "bp": ["Egzamen ekri MA: yon pati nan Sante mantal (4 kesyon sou 60) ak Konpetans debaz swen enfimyè (8).", "MA written exam: part of Mental Health (4 of 60 questions) and Basic Nursing Skills (8)."], "title": ["Swen nan fen lavi", "End-of-life care"], "src": ["S1"], "sections": [{"h": ["Lapenn", "Grief"], "src": ["S1"], "b": [["li", "Etap lapenn yo se: refize, kòlè, negosye, depresyon ak aksepte. Moun ka pase nan yo nan nenpòt lòd, repase nan yo oswa sote kèk.", "The stages of grief are denial, anger, bargaining, depression and acceptance. People may go through them in any order, repeat them or skip some."], ["li", "Kòlè souvan soti nan pèdi kontwòl, epi l ka tonbe sou anplwaye yo. Pa pran l pou tèt ou. Kite moun nan pale, men kenbe limit ak respè.", "Anger often comes from losing control and may be aimed at staff. Do not take it personally. Let the person vent, while keeping respectful limits."]]}, {"h": ["Ospis ak volonte davans", "Hospice and advance directives"], "src": ["S1"], "b": [["li", "Swen ospis se pou yon moun ki gen yon maladi ki p ap geri. Li konsantre sou konfò, pa sou gerizon, epi li pa fè moun nan mouri pi vit.", "Hospice care is for a person with a terminal illness. It focuses on comfort, not cure, and does not hasten death."], ["li", "Yon lòd DNR (pa reyanime) konsène sèlman CPR. Tout lòt swen kontinye.", "A DNR (do not resuscitate) order covers only CPR. All other care continues."], ["li", "Sipòte volonte rezidan an. Si w wè yon konfli sou sa, di enfimyè a.", "Support the resident's wishes. If you see a conflict about them, tell the nurse."]]}, {"h": ["Swen konfò", "Comfort care"], "src": ["S1"], "b": [["li", "Di enfimyè a 10 a 15 minit anvan w bay swen, pou yo ka tcheke epi trete doulè a anvan.", "Tell the nurse 10 to 15 minutes before you give care, so pain can be checked and treated first."], ["li", "Swen bouch: yon ti baton koton mouye ak krèm pou po bouch souvan. Chanje pozisyon souvan pou pwoteje po a, jan plan swen an di.", "Mouth care: a moist swab and lip balm often. Reposition often to protect the skin, as the care plan says."], ["li", "Kenbe chanm nan trankil, ak limyè moun nan santi l alèz, san sant fò.", "Keep the room quiet, with lighting the person finds comfortable and no strong scents."]]}, {"h": ["Lè lanmò pre", "When death is near"], "src": ["S1"], "b": [["li", "Siy yo: men ak pye ki frèt, ki ka pal oswa ble; po vyolèt ak tach, souvan sou janm ak pye; respirasyon ki pa regilye ak poz; bri nan souf la; mwens manje, bwè ak pipi.", "Signs: cool hands and feet that may look pale or bluish; purple, mottled skin, often on the legs and feet; irregular breathing with pauses; rattling breath sounds; less intake and output."], ["li", "Tande se dènye sans ki rete. Eksplike chak swen, kontinye pale ak moun nan tankou l konprann, epi fè atansyon ak sa w di bò kote l.", "Hearing is the last sense to fail. Explain each task, keep talking to the person as if they understand, and be careful what you say nearby."]]}], "terms": [["hospice", "ospis"], ["do not resuscitate (DNR)", "pa reyanime (DNR)"], ["mottling", "po ak tach"], ["grief", "lapenn"], ["comfort care", "swen konfò"]], "qs": [["n701", 2, ["grief", "lapenn"], ["Kisa ki vre sou etap lapenn yo?", "Tout moun pase nan yo nan menm lòd", "Yo toujou fini nan yon semèn", "Yon moun ka pase nan yo nan nenpòt lòd oswa repase nan yo", "Se fanmi an sèlman ki pase nan yo", "Refize, kòlè, negosye, depresyon ak aksepte ka vini nan nenpòt lòd, repete, oswa pa vini ditou."], ["What is true about the stages of grief?", "Everyone goes through them in the same order", "They always end in one week", "A person may go through them in any order or repeat them", "Only the family goes through them", "Denial, anger, bargaining, depression and acceptance can come in any order, repeat, or be skipped."]], ["n702", 0, ["anger", "kòlè"], ["Yon rezidan k ap mouri ap rele sou ou pandan w ap chanje dra l. Ki pi bon repons lan?", "Rete kalm, pa pran l pou tèt ou, epi kite l eksprime santiman l", "Rele sou li tou pou l sispann", "Ale epi refize okipe l", "Di l li malelve", "Kòlè se yon etap nòmal nan lapenn, epi souvan li soti nan pèdi kontwòl. Kite l pale, men kenbe limit ak respè."], ["A dying resident yells at you while you change his sheets. What is the best response?", "Stay calm, do not take it personally, and let him express his feelings", "Yell back so he stops", "Leave and refuse to care for him", "Tell him he is being rude", "Anger is a normal stage of grief and often comes from losing control. Let him vent, while keeping respectful limits."]], ["n703", 3, ["hearing", "tande"], ["Yon rezidan k ap mouri pa reponn ankò. Kijan pou w pale pandan w ap bay swen?", "Pa pale, paske li pa ka tande", "Pale sèlman ak kòlèg ki nan chanm nan", "Rele fò pou l ka tande", "Eksplike sa w ap fè epi pale avè l tankou l konprann", "Tande se dènye sans ki rete. Eksplike chak swen epi fè atansyon ak sa yo di bò kote l."], ["A dying resident no longer responds. How should you talk while you give care?", "Do not talk, since she cannot hear", "Talk only with coworkers in the room", "Shout so she can hear", "Explain what you are doing and talk to her as if she understands", "Hearing is the last sense to fail. Explain each task and be careful what is said nearby."]], ["n704", 1, ["mouth care", "swen bouch"], ["Bouch ak po bouch yon rezidan k ap mouri sèk. Kisa ou fè?", "Vide dlo nan bouch li", "Sèvi ak yon ti baton koton mouye ak krèm pou po bouch souvan", "Pa fè anyen; sa pa enpòtan kounye a", "Ba l sirèt di pou l souse", "Swen bouch souvan ak yon ti baton koton mouye ak krèm pou po bouch kenbe moun k ap mouri a alèz. Vide dlo ka fè l toufe."], ["A dying resident's mouth and lips are dry. What do you do?", "Pour water into the mouth", "Use a moist swab and lip balm often", "Do nothing; it does not matter now", "Give hard candy to suck on", "Frequent mouth care with a moist swab and lip balm keeps a dying person comfortable. Pouring water can cause choking."]], ["n705", 2, ["mottling", "po ak tach"], ["Ki siy ki ka vle di lanmò pre?", "Pye cho ak woz, ak bon apeti", "Plis pipi pase dabitid", "Pye frèt ak tach, ak respirasyon ki gen gwo poz", "Pale ak mache plis", "Po frèt, pal oswa ak tach, respirasyon ki pa regilye ak poz, bri nan souf ak mwens manje, bwè ak pipi se siy lanmò ka pre. Rapòte chanjman yo bay enfimyè a."], ["Which signs can mean death is near?", "Warm, pink feet and a strong appetite", "More urine than usual", "Cool, mottled feet and breathing with long pauses", "Talking and walking more", "Cool, pale or mottled skin, irregular breathing with pauses, rattling breath and less intake and output are signs death may be near. Report changes to the nurse."]], ["n706", 0, ["hospice", "ospis"], ["Ki objektif prensipal swen ospis?", "Konfò, pa gerizon", "Geri maladi a", "Fè lanmò vini pi vit", "Voye rezidan an lopital", "Ospis konsantre sou konfò yon moun ki gen yon maladi ki p ap geri. Li pa fè lanmò vini pi vit."], ["What is the main goal of hospice care?", "Comfort, not cure", "Curing the illness", "Making death come faster", "Moving the resident to a hospital", "Hospice focuses on comfort for a person with a terminal illness. It does not hasten death."]], ["n707", 3, ["do not resuscitate (DNR)", "pa reyanime (DNR)"], ["Yon rezidan gen yon lòd DNR. Kisa sa vle di pou swen w bay?", "Sispann tout swen, ansanm ak manje", "Sispann vire l ak benyen l", "Pa rele enfimyè a si l vin pi mal", "Pa gen CPR; tout lòt swen kontinye", "Yon lòd DNR konsène sèlman CPR. Kontinye bay tout lòt swen epi rapòte chanjman bay enfimyè a."], ["A resident has a DNR order. What does it mean for your care?", "Stop all care, including meals", "Stop turning and bathing him", "Do not call the nurse if he gets worse", "No CPR; all other care continues", "A DNR order covers only CPR. Keep giving all other care and report changes to the nurse."]], ["n708", 1, ["pain", "doulè"], ["Ou pral chanje pozisyon yon rezidan k ap mouri ki gen doulè. Kisa pou w fè an premye?", "Deplase l vit pou fini ak sa", "Di enfimyè a 10 a 15 minit anvan, pou yo ka trete doulè a", "Pa chanje pozisyon l pou rès jounen an", "Ba l yon grenn doulè nan chariot la", "Fè enfimyè a konnen 10 a 15 minit anvan swen an pou yo ka tcheke doulè a epi bay medikaman si sa nesesè."], ["You are about to reposition a dying resident who has pain. What should you do first?", "Move him quickly to get it over with", "Tell the nurse 10 to 15 minutes before, so pain can be treated", "Skip repositioning for the rest of the day", "Give him a pain pill from the cart", "Let the nurse know 10 to 15 minutes before care so pain can be checked and medicine given if needed."]]]});
window.CNA_SEC = {"n201": 0, "n202": 0, "n203": 1, "n204": 1, "n205": 1, "n206": 2, "n207": 2, "n208": 2, "n209": 1, "n210": 3, "n211": 3, "n212": 3, "n213": 3, "n214": 1, "n215": 0, "n216": 0, "n217": 1, "n218": 0, "n219": 0, "n220": 0, "n221": 3, "n222": 1, "n223": 0, "n224": 0, "n225": 3, "n226": 3, "n227": 3, "n228": 3, "n229": 3, "n230": 3, "n301": 0, "n302": 0, "n303": 0, "n304": 0, "n305": 1, "n306": 1, "n307": 2, "n308": 2, "n309": 3, "n310": 3, "n311": 3, "n312": 0, "n313": 0, "n314": 0, "n315": 0, "n401": 0, "n402": 1, "n403": 1, "n404": 2, "n405": 2, "n406": 3, "n407": 3, "n408": 4, "n501": 0, "n502": 1, "n503": 2, "n504": 2, "n505": 3, "n506": 0, "n601": 0, "n602": 0, "n603": 0, "n604": 2, "n605": 2, "n606": 3, "n701": 0, "n702": 0, "n703": 3, "n704": 2, "n705": 3, "n706": 1, "n707": 1, "n708": 2};
